          g2.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + dur);
          o2.connect(g2); g2.connect(master); o2.start(ctx.currentTime + 0.05); o2.stop(ctx.currentTime + dur + 0.05);
